check(SUN_Database::canonical_json(array('b'=>2,'a'=>1))==='{"a":1,"b":2}','canonical JSON sorting');
check((bool)preg_match('/^[a-f0-9\-]{36}$/',SUN_Database::uuid()),'UUID format');
