for($i=0;$i<5;$i++){SUN_Provider_Circuit::record_failure('push');}check(true===SUN_Provider_Circuit::is_open('push'),'provider circuit opens after repeated failures');SUN_Provider_Circuit::record_success('push');check(false===SUN_Provider_Circuit::is_open('push'),'provider circuit resets after success');
$auth=new SUN_Auth();check(false===$auth->is_recipient_eligible(5),'File 00 unavailable fails closed');
