$assertions=$auth->assertions(5);check(true===$assertions['owner_available']&&'Asia/Karachi'===$assertions['timezone'],'canonical claims projected');check(true===$assertions['email_verified']&&true===$assertions['phone_verified'],'verified channel claims projected');check(true===$assertions['step_up_verified']&&true===$assertions['founder'],'governance claims projected');check(true===$auth->is_founder(5),'canonical File 00 Founder claim authorizes Founder');
