$bad_owner=$event;$bad_owner['owner']='File 18';$bad_owner_result=$validator->validate($bad_owner);check(is_wp_error($bad_owner_result)&&'sun_event_owner_mismatch'===$bad_owner_result->get_error_code(),'producer owner binding');
$bad_schema=$event;$bad_schema['schema_version']='2.0';$bad_schema_result=$validator->validate($bad_schema);check(is_wp_error($bad_schema_result)&&'sun_schema_version_unsupported'===$bad_schema_result->get_error_code(),'producer schema allowlist');
$bad_scope=$event;$bad_scope['subscription_scope']=array('type'=>'private_message_body','id'=>'x','required'=>true);check(is_wp_error($validator->validate($bad_scope)),'invalid subscription scope rejected');
$event['recipients']=array(array('role'=>'subscriber'));check(is_wp_error($validator->validate($event)),'broad role recipient rejection');
$event['recipients']=array(5);$event['event_type']='bad type';check(is_wp_error($validator->validate($event)),'invalid event type rejection');
SUN_Producer_Registry::register_runtime('file21',array('owner'=>'File 21','event_types'=>array('Social.*','Publishing.*'),'schema_versions'=>array('1.0')));
$bulletin=array('producer'=>'file21','owner'=>'File 21','event_id'=>'bulletin:1','event_type'=>'Social.CreatorBulletinPublished','schema_version'=>'1.0','occurred_at'=>gmdate(DATE_ATOM),'recipients'=>array(5),'data'=>array('summary'=>'Bulletin'));
$bulletin_without_scope=$validator->validate($bulletin);check(is_wp_error($bulletin_without_scope)&&'sun_subscription_scope_required'===$bulletin_without_scope->get_error_code(),'creator bulletin requires explicit opt-in scope');
$bulletin['subscription_scope']=array('type'=>'person','id'=>'doctor-55','required'=>true);check(!is_wp_error($validator->validate($bulletin)),'creator bulletin accepts required opt-in scope');
